INSERT INTO articles (id,author_id,category_id,title,slug,content,excerpt,image_path,image_alt,status,featured,views,published_at) VALUES (1,2,1,'Lima abre nuevos espacios peatonales para recuperar la vida de barrio','lima-abre-nuevos-espacios-peatonales-para-recuperar-la-vida-de-barrio','<p>Los espacios de encuentro ayudan a construir confianza entre vecinos. La iniciativa reúne a organizaciones locales, comerciantes y estudiantes en una agenda compartida.</p><h2>Una iniciativa que conecta</h2><p>Las actividades se organizarán por etapas para que cada barrio pueda adaptar la propuesta a sus necesidades. Los participantes piden que la información sobre horarios y resultados permanezca abierta.</p><h2>La mirada de la comunidad</h2><p>En este reportaje de demostración sobre «Lima abre nuevos espacios peatonales para recuperar la vida de barrio», las voces locales recuerdan que escuchar es el primer paso para construir acuerdos.</p><blockquote><p>Los cambios duraderos se construyen con participación y una evaluación transparente.</p></blockquote><h2>Qué viene después</h2><p>Los próximos encuentros permitirán revisar los avances y recoger propuestas. Esta noticia es un ejemplo ficticio para probar el portal; no describe un anuncio oficial.</p>','Los espacios de encuentro ayudan a construir confianza entre vecinos. La iniciativa reúne a organizaciones locales, comerciantes y estudiantes en una agenda compartida.','assets/news-1.webp','Ilustración editorial de actualidad con paisaje y espacios de encuentro','publicado',1,287,DATE_SUB(NOW(), INTERVAL 2 HOUR));
