INSERT INTO articles (id,author_id,category_id,title,slug,content,excerpt,image_path,image_alt,status,featured,views,published_at) VALUES (59,2,8,'La lectura compartida acerca a familias y escuelas','la-lectura-compartida-acerca-a-familias-y-escuelas','<p>El bienestar también depende de los vínculos y de los espacios que habitamos. La propuesta ofrece actividades sencillas que las familias pueden adaptar a sus rutinas.</p><h2>Una iniciativa que conecta</h2><p>Los equipos locales recogerán sugerencias para ajustar horarios y formatos. La participación es voluntaria y no sustituye la atención profesional cuando se necesita.</p><h2>La mirada de la comunidad</h2><p>En este reportaje de demostración sobre «La lectura compartida acerca a familias y escuelas», las voces locales recuerdan que escuchar es el primer paso para construir acuerdos.</p><blockquote><p>Los cambios duraderos se construyen con participación y una evaluación transparente.</p></blockquote><h2>Qué viene después</h2><p>Los próximos encuentros permitirán revisar los avances y recoger propuestas. Esta noticia es un ejemplo ficticio para probar el portal; no describe un anuncio oficial.</p>','El bienestar también depende de los vínculos y de los espacios que habitamos. La propuesta ofrece actividades sencillas que las familias pueden adaptar a sus rutinas.','assets/news-8.webp','Ilustración editorial de bienestar con paisaje y espacios de encuentro','archivado',0,1233,DATE_SUB(NOW(), INTERVAL 118 HOUR));
INSERT INTO article_tag VALUES (59,8),(59,1);
INSERT INTO articles (id,author_id,category_id,title,slug,content,excerpt,image_path,image_alt,status,featured,views,published_at) VALUES (60,3,8,'Diseñar calles amables también mejora la vida cotidiana','disenar-calles-amables-tambien-mejora-la-vida-cotidiana','<p>El bienestar también depende de los vínculos y de los espacios que habitamos. La propuesta ofrece actividades sencillas que las familias pueden adaptar a sus rutinas.</p><h2>Una iniciativa que conecta</h2><p>Los equipos locales recogerán sugerencias para ajustar horarios y formatos. La participación es voluntaria y no sustituye la atención profesional cuando se necesita.</p><h2>La mirada de la comunidad</h2><p>En este reportaje de demostración sobre «Diseñar calles amables también mejora la vida cotidiana», las voces locales recuerdan que escuchar es el primer paso para construir acuerdos.</p><blockquote><p>Los cambios duraderos se construyen con participación y una evaluación transparente.</p></blockquote><h2>Qué viene después</h2><p>Los próximos encuentros permitirán revisar los avances y recoger propuestas. Esta noticia es un ejemplo ficticio para probar el portal; no describe un anuncio oficial.</p>','El bienestar también depende de los vínculos y de los espacios que habitamos. La propuesta ofrece actividades sencillas que las familias pueden adaptar a sus rutinas.','assets/news-8.webp','Ilustración editorial de bienestar con paisaje y espacios de encuentro','archivado',0,1370,DATE_SUB(NOW(), INTERVAL 120 HOUR));
INSERT INTO article_tag VALUES (60,8),(60,1);
